import {compareInvoices,invoiceSortOptions} from './invoice-sort.js';
import {scopedUrl} from './emitters.js';
import {today} from './model.js?v=analysis-1';
import {balances,available,summary,cashTotal,periodBounds,currency,cents,active,paymentName,invoicePayments,paymentAmount} from './ledger.js';
import {createImportView} from './import-ui.js';
import {incomeWorkbook} from './income-excel.js';
export function createAnalysis(ctx){
 const {getDb,setDb,database,shell,heading,esc,icon,toast,modal,openInvoice,beforeAction,isAdmin,ownerLabel}=ctx;
 const state={tab:'summary',mode:'year',year:today().slice(0,4),month:today().slice(5,7),quarter:String(Math.ceil(Number(today().slice(5,7))/3)),start:today().slice(0,4)+'-01-01',end:today(),asOf:today(),client:'',search:'',status:'pending',sort:'new',group:false,selected:new Set()};
 if(new URLSearchParams(location.search).get('tab')==='todas'){state.tab='allInvoices';state.status='all';}
 const statusName={paid:'Pagada',partial:'Parcialmente pagada',unpaid:'No pagada'};
 const date=d=>d?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).replaceAll('.',''):'—';
 const customer=i=>i.clientSnapshot||getDb().clients.find(c=>c.id===i.clientId)||{name:'Sin cliente'};
 const statusBadge=b=>`<span class="badge ${b.status==='unpaid'?'draft':b.status==='partial'?'partial':''}">${statusName[b.status]}</span>`;
 const range=()=>periodBounds(state.mode,state.year,state.month,state.quarter,state.start,state.end);
 const apiCommand=async cmd=>{await beforeAction();const value=await database.command(cmd);setDb(value);return value;};
 const empty=(message,button='')=>`<div class="empty">${icon('chart')}<h3>${message}</h3><p>Los saldos se calculan a partir de las facturas y los movimientos registrados.</p>${button}</div>`;
 const importer=createImportView({...ctx,onCancel:()=>{state.tab='summary';render();},onDone:()=>{state.tab='pending';render();},command:apiCommand,date,currency});
 function filters(){const db=getDb(),financialInvoices=db.invoices.filter(i=>!i.isExample&&!i.isDemo&&!i.vfTest);const years=[...new Set([today().slice(0,4),...financialInvoices.map(i=>i.date.slice(0,4))])].sort().reverse();return `<section class="analysis-filters panel"><div class="field"><label for="an-mode">Periodo de emisión</label><select id="an-mode" data-filter="mode">${[['year','Año completo'],['quarter','Trimestre'],['month','Mes'],['custom','Personalizado']].map(([v,l])=>`<option value="${v}" ${state.mode===v?'selected':''}>${l}</option>`).join('')}</select></div>${state.mode==='custom'?`<div class="field"><label for="an-start">Desde</label><input id="an-start" type="date" data-filter="start" value="${state.start}"></div><div class="field"><label for="an-end">Hasta</label><input id="an-end" type="date" data-filter="end" value="${state.end}"></div>`:`<div class="field"><label for="an-year">Año</label><select id="an-year" data-filter="year">${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select></div>${state.mode==='month'?`<div class="field"><label for="an-month">Mes</label><select id="an-month" data-filter="month">${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${Number(state.month)===i+1?'selected':''}>${new Intl.DateTimeFormat('es-ES',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,i,15)))}</option>`).join('')}</select></div>`:state.mode==='quarter'?`<div class="field"><label for="an-quarter">Trimestre</label><select id="an-quarter" data-filter="quarter">${[1,2,3,4].map(q=>`<option value="${q}" ${Number(state.quarter)===q?'selected':''}>${q}.º trimestre</option>`).join('')}</select></div>`:''}`}
 <div class="field"><label for="an-asof">Situación de cobro a fecha</label><input id="an-asof" type="date" data-filter="asOf" value="${state.asOf}" max="${today()}"></div><div class="field filter-client"><label for="an-client">Cliente de las facturas</label><select id="an-client" data-filter="client"><option value="">Todos los clientes</option>${db.clients.filter(c=>financialInvoices.some(i=>i.clientId===c.id)).map(c=>`<option value="${esc(c.id)}" ${state.client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><button class="btn analysis-excel" data-fa="excel">${icon('download')} Descargar Excel</button></section>`;}
 function filteredBalances(onlyPeriod=true){const r=range();return balances(getDb(),state.asOf).filter(b=>(!onlyPeriod||(b.original.date>=r.start&&b.original.date<=r.end))&&(!state.client||b.invoice.clientId===state.client)&&(!state.search||`${b.invoice.number} ${customer(b.invoice).name} ${b.invoice.lines.map(l=>l.description).join(' ')} ${invoicePayments(getDb(),b,state.asOf).map(p=>p.name).join(' ')}`.toLowerCase().includes(state.search.toLowerCase()))&&(state.tab!=='pending'||b.pendingCents>0)&&(state.status==='all'||state.status==='pending'&&b.pendingCents>0||state.status===b.status));}

 function stats(){const s=summary(getDb(),range(),state.asOf,state.client);return `<div class="finance-stats">${[['Emitido en el periodo',s.totalCents,`${currency(s.baseCents)} base · ${currency(s.vatCents)} IVA`],['Cobrado de esas facturas',s.paidCents,`${s.cohort.length} facturas · ${currency(s.adjustedCents)} en ajustes`],['Pendiente del periodo',s.pendingCents,'Saldo de las facturas emitidas en el periodo'],['Pendiente total',s.pendingAllCents,'Todos los periodos, incluidos años anteriores']].map(([label,value,sub],i)=>`<article class="stat ${i===2?'stat-outstanding':''}"><div class="stat-label">${icon(i===0?'invoice':i===1?'check':'clock')}${label}</div><div class="stat-value">${currency(value)}</div><small>${sub}</small></article>`).join('')}</div>${s.creditAllCents?`<div class="notice">Hay ${currency(s.creditAllCents)} a favor de clientes tras rectificaciones o devoluciones. Revisa sus movimientos antes de repartir nuevos cobros.</div>`:''}`;}
 function paymentCell(b){const linked=invoicePayments(getDb(),b,state.asOf);return linked.length?linked.map(p=>`<div class="invoice-linked-payment"><button class="rowlink" data-fa-payment="${esc(p.payment.id)}">${esc(p.name)}</button><small class="cell-secondary">${currency(p.amountCents)} · ${date(p.payment.date)}</small></div>`).join(''):`<span class="muted">${b.status==='paid'&&b.adjustedCents?'Liquidada con ajustes':'Sin cobros aplicados'}</span>`;}
 function rowsTable(list,selectable=false){
  if(!list.length)return empty('No hay facturas en esta selección',isAdmin()?`<button class="btn" data-fa="import">Revisar Excel de ingresos</button>`:'');
  let previous=null;const rows=[...list].sort((a,b)=>(state.group?(customer(a.invoice).name.localeCompare(customer(b.invoice).name)||a.invoice.clientId.localeCompare(b.invoice.clientId)):0)||compareInvoices({...a.invoice,date:a.original.date},{...b.invoice,date:b.original.date},state.sort));
  return `<div class="tablewrap"><table class="finance-table"><thead><tr>${selectable?'<th scope="col"><span class="sr-only">Seleccionar</span></th>':''}<th scope="col">Factura / cliente</th><th scope="col">Concepto</th><th scope="col">Emisión</th><th scope="col" class="num">Total</th><th scope="col" class="num">Cobrado</th><th scope="col" class="num">Ajustes</th><th scope="col" class="num">Pendiente</th><th scope="col">Estado</th><th scope="col">Pago(s)</th><th scope="col" aria-label="Acciones"></th></tr></thead><tbody>${rows.map(b=>{
   let group='';const c=customer(b.invoice);if(state.group&&previous!==b.invoice.clientId){previous=b.invoice.clientId;const sum=rows.filter(x=>x.invoice.clientId===previous).reduce((n,x)=>n+x.pendingCents,0);group=`<tr class="finance-group"><td colspan="${selectable?11:10}">${esc(c.name)}<strong>${currency(sum)} pendiente</strong></td></tr>`;}
   const descriptions=b.invoice.lines.map(l=>l.description.trim()).filter(Boolean);
   return group+`<tr data-finance-invoice="${esc(b.invoice.id)}">${selectable?`<td><input type="checkbox" class="small-check" data-pick="${esc(b.invoice.id)}" aria-label="Seleccionar ${esc(b.invoice.number)}" ${state.selected.has(b.invoice.id)?'checked':''} ${b.pendingCents<=0?'disabled':''}></td>`:''}<td><button class="rowlink" data-fa-invoice="${esc(b.invoice.id)}">${esc(b.invoice.number)}</button><small class="cell-secondary">${esc(c.name)}</small>${isAdmin()?`<small class="cell-secondary invoice-owner">${esc(ownerLabel(b.invoice))}</small>`:''}${b.memberIds.length>1?'<small class="cell-secondary">Importe actualizado por rectificativa</small>':''}${b.invoice.isDemo?'<small class="cell-secondary">Ejemplo</small>':''}</td><td class="concept-cell">${descriptions.length?descriptions.map(text=>`<p>${esc(text)}</p>`).join(''):'<span class="muted">Sin concepto</span>'}</td><td>${date(b.original.date)}</td><td class="num">${currency(b.totalCents)}</td><td class="num">${currency(b.paidCents)}</td><td class="num">${currency(b.adjustedCents)}</td><td class="num"><strong>${currency(b.pendingCents)}</strong></td><td>${statusBadge(b)}</td><td class="invoice-payments-cell">${paymentCell(b)}</td><td><div class="invoice-row-actions"><button class="iconbtn" data-rename-invoice="${esc(b.invoice.id)}" aria-label="Editar número de ${esc(b.invoice.number)}">${icon('edit')}</button>${b.pendingCents>0?`<button class="btn" data-fa-collect="${esc(b.invoice.id)}" aria-label="Registrar cobro de ${esc(b.invoice.number)}">Cobrar</button>`:''}<button class="iconbtn" data-fa-history="${esc(b.invoice.id)}" aria-label="Historial de ${esc(b.invoice.number)}">${icon('clock')}</button></div></td></tr>`;
  }).join('')}</tbody></table></div>`;
 }

 function overview(){const db=getDb(),r=range(),s=summary(db,r,state.asOf,state.client);const months=[];let dt=new Date(r.start+'T12:00:00Z');dt.setUTCDate(1);const until=new Date(r.end+'T12:00:00Z');for(let x=0;x<36&&dt<=until;x++,dt.setUTCMonth(dt.getUTCMonth()+1)){const key=dt.toISOString().slice(0,7),start=key+'-01',end=new Date(Date.UTC(dt.getUTCFullYear(),dt.getUTCMonth()+1,0)).toISOString().slice(0,10);const emitted=s.cohort.filter(b=>b.original.date.startsWith(key)).reduce((n,b)=>n+b.totalCents,0);months.push({key,label:new Intl.DateTimeFormat('es-ES',{month:'short',year:'2-digit',timeZone:'UTC'}).format(dt),emitted,cash:cashTotal(db,start<r.start?r.start:start,end>r.end?r.end:end,state.asOf)});}
 const max=Math.max(1,...months.flatMap(m=>[m.emitted,Math.abs(m.cash)]));return stats()+`${s.withholdingCents?`<div class="notice">Las facturas del periodo incluyen ${currency(s.withholdingCents)} de retenciones. Los totales y el pendiente muestran el importe a cobrar después de la retención.</div>`:''}<section class="panel chart-panel"><div class="sectionhead"><div><h2>${state.mode==='year'?'El año':state.mode==='quarter'?'El trimestre':state.mode==='month'?'El mes':'El periodo'}, con perspectiva</h2><p class="muted">La emisión se agrupa por la fecha original; los ingresos, por su fecha bancaria.</p></div><button class="btn" data-fa="report">${icon('download')} Descargar informe</button></div><div class="chart-legend"><span><i></i>Facturación neta</span><span><i class="cash-dot"></i>${isAdmin()?'Ingresos bancarios netos · todos los clientes':'Cobros propios · parte visible de ingresos compartidos'}</span></div><div class="monthly-chart" role="img" aria-label="Comparativa mensual de facturación e ingresos">${months.map(m=>`<div class="chart-month" title="${esc(m.label)}: emitido ${currency(m.emitted)}, ingresos ${currency(m.cash)}"><div class="chart-bars"><i style="height:${Math.max(1,m.emitted/max*130)}px"></i><i class="cash-bar ${m.cash<0?'cash-negative':''}" style="height:${Math.max(1,Math.abs(m.cash)/max*130)}px"></i></div><span>${esc(m.label)}</span></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th scope="col">Mes</th><th scope="col" class="num">Emitido neto</th><th scope="col" class="num">Ingresos bancarios netos</th></tr></thead><tbody>${months.map(m=>`<tr><td><button class="rowlink" data-fa-month="${m.key}">${esc(m.label)}</button></td><td class="num">${currency(m.emitted)}</td><td class="num">${currency(m.cash)}</td></tr>`).join('')}</tbody></table></div></section><div class="notice">Las rectificativas por sustitución actualizan el importe de la factura original y conservan sus cobros. Los ajustes liquidan deuda sin registrar otro ingreso bancario. ${state.asOf<today()?'Estás viendo una fecha de corte histórica.':''}</div>`;}
 function pending(){const isAll=state.tab==='allInvoices',list=filteredBalances(true);const statusOptions=isAll?[['all','Todos los estados'],['unpaid','No pagadas'],['partial','Parcialmente pagadas'],['paid','Pagadas']]:[['pending','Con saldo pendiente'],['unpaid','No pagadas'],['partial','Parcialmente pagadas']];return stats()+`<section class="panel"><div class="toolbar"><div class="search">${icon('search')}<input id="fa-search" placeholder="Factura, cliente, concepto o pago…" aria-label="${isAll?'Buscar todas las facturas':'Buscar pendientes'}" value="${esc(state.search)}"></div><div class="actions"><select id="fa-sort" aria-label="Ordenar facturas">${invoiceSortOptions(state.sort)}</select><select id="fa-status" aria-label="Estado de cobro">${statusOptions.map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><label class="check-label"><input type="checkbox" id="fa-group" ${state.group?'checked':''}>Agrupar por cliente</label></div></div><div id="finance-invoice-rows">${rowsTable(list,true)}</div><div class="tablefoot"><span id="finance-result-label">${list.length} facturas · ${currency(list.reduce((n,b)=>n+b.pendingCents,0))} pendiente</span><button class="btn primary" data-fa="collect-selected" ${!state.selected.size?'disabled':''}>Registrar cobro de la selección <span id="picked-count">(${state.selected.size})</span></button></div></section><p class="analysis-footnote">El listado respeta el periodo de emisión elegido. <button class="clear-link" data-fa="all-outstanding">Ver deuda de todos los años</button></p>`;}
 function receipts(){const db=getDb(),r=range();const list=db.payments.filter(p=>!p.vfTest&&p.date>=r.start&&p.date<=r.end&&p.date<=state.asOf&&(!state.search||`${paymentName(p)} ${p.payer} ${p.reference} ${p.account}`.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));const received=cashTotal(db,r.start,r.end,state.asOf),unallocated=db.payments.filter(p=>!p.vfTest&&active(p,state.asOf)).reduce((n,p)=>n+available(db,p,state.asOf),0);return `<div class="finance-stats receipt-stats"><article class="stat"><div class="stat-label">${isAdmin()?'Ingresos bancarios netos del periodo':'Cobros propios del periodo'}</div><div class="stat-value">${currency(received)}</div><small>Ingresos menos devoluciones · fecha de ingreso</small></article><article class="stat"><div class="stat-label">Anticipos y saldo sin aplicar</div><div class="stat-value">${currency(unallocated)}</div><small>Todos los periodos · disponible para repartir o devolver</small></article></div><section class="panel"><div class="toolbar"><div class="search">${icon('search')}<input id="fa-search" placeholder="Pagador, referencia o cuenta…" aria-label="Buscar cobros" value="${esc(state.search)}"></div><button class="btn" data-fa="report-payments">${icon('download')} Exportar cobros</button></div>${list.length?`<div class="tablewrap"><table><thead><tr><th scope="col">Fecha</th><th scope="col">Pago / pagador</th><th scope="col">Cuenta receptora</th><th scope="col" class="num">Recibido</th><th scope="col" class="num">Sin aplicar</th><th scope="col">Estado</th><th scope="col"></th></tr></thead><tbody>${list.map(p=>`<tr><td>${date(p.date)}</td><td><button class="rowlink" data-fa-payment="${esc(p.id)}">${esc(paymentName(p))}</button><small class="cell-secondary truncate-reference">${esc(p.payer)}${p.reference&&p.reference!==paymentName(p)?' · '+esc(p.reference):''}</small></td><td>${esc(p.account)}</td><td class="num">${currency(paymentAmount(db,p,state.asOf))}</td><td class="num">${currency(available(db,p,state.asOf))}</td><td><span class="badge ${p.voidDate&&p.voidDate<=state.asOf?'draft':''}">${p.voidDate&&p.voidDate<=state.asOf?'Anulado':available(db,p,state.asOf)>0?'Saldo disponible':'Aplicado'}</span></td><td><button class="iconbtn" data-fa-payment="${esc(p.id)}" aria-label="Ver cobro de ${esc(p.payer)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay cobros en este periodo')}<div class="tablefoot">${!isAdmin()?'En ingresos compartidos se muestra solo lo aplicado a tus facturas. ':''}Las transferencias agrupadas aparecen una sola vez. El filtro de cliente de las facturas no limita los pagadores de esta vista.</div></section>`;}
 function render(){if(state.tab==='import')return importer.render();const r=range();const invalid=!r.start||!r.end||r.start>r.end||!state.asOf||state.asOf>today();shell(heading('Análisis',isAdmin()?'Toda la facturación y los cobros del emisor seleccionado.':'El análisis de tus facturas y tus cobros.',` ${isAdmin()?`<button class="btn" data-fa="import">${icon('download')} Importar Excel</button>`:''}<button class="btn primary" data-fa="new-payment">${icon('plus')} Registrar cobro</button>`)+`<div class="analysis-tabs tabs" role="group" aria-label="Vistas de análisis">${[['summary','Resumen'],['allInvoices','Todas'],['pending','Pendientes de cobro'],['payments','Cobros'],['audit','Historial']].map(([v,l])=>`<button class="tab ${state.tab===v?'active':''}" data-fa-tab="${v}" aria-pressed="${state.tab===v}">${l}</button>`).join('')}</div>${state.tab!=='audit'?filters():''}${invalid&&state.tab!=='audit'?'<div class="error">Revisa el intervalo y la fecha de consulta.</div>':state.tab==='summary'?overview():['pending','allInvoices'].includes(state.tab)?pending():state.tab==='payments'?receipts():`<section class="panel" id="audit-rows"><div class="empty">Cargando historial…</div></section>`}`,'Análisis');if(state.tab==='audit')loadAudit();}
 async function loadAudit(){try{const data=await fetch('/api/audit?excludeExamples=1').then(r=>r.json());const el=document.querySelector('#audit-rows');if(el)el.innerHTML=`<div class="formpanel"><h2>Historial de cambios</h2><p class="summary-note">Cada operación conserva su fecha y revisión. Las anulaciones mantienen el movimiento original.</p></div><div class="tablewrap"><table><thead><tr><th scope="col">Fecha</th><th scope="col">Operación</th><th scope="col">Revisión</th></tr></thead><tbody>${data.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString('es-ES'))}</td><td>${esc(a.description)}</td><td>${a.revision}</td></tr>`).join('')}</tbody></table></div>`;}catch{toast('No se ha podido cargar el historial.');}}
 function showDialog(content,wide=false){modal.className=wide?'finance-modal':'';modal.innerHTML=`<button class="iconbtn close" data-fa="close" aria-label="Cerrar">${icon('close')}</button>${content}`;if(!modal.open)modal.showModal();}
 const allOpen=()=>balances(getDb(),today()).filter(b=>b.pendingCents>0).sort((a,b)=>customer(a.invoice).name.localeCompare(customer(b.invoice).name)||a.original.date.localeCompare(b.original.date));
 function paymentForm(selected=[],paymentId=null){const db=getDb(),pay=db.payments.find(p=>p.id===paymentId),testMode=selected.some(id=>db.invoices.find(i=>i.id===id)?.vfTest)||!!pay?.vfTest,open=testMode?balances(db,today(),true,true).filter(b=>b.invoice.vfTest&&b.pendingCents>0):allOpen();if(selected.some(id=>!open.some(b=>b.invoice.id===id))){for(const b of balances(db,today(),true,true))if(selected.includes(b.invoice.id)&&!open.some(x=>x.invoice.id===b.invoice.id)&&b.pendingCents>0)open.push(b);}
 // A receipt only pays invoices of the client who paid.
 const clientOf=id=>db.invoices.find(i=>i.id===id)?.clientId||'',owner=pay?receiptClient(db,pay):clientOf(selected[0]);selected=selected.filter(id=>clientOf(id)===owner);paymentOpen=open;
 const names=new Map(db.clients.map(c=>[c.id,c.name]));for(const b of open)if(b.invoice.clientId&&!names.has(b.invoice.clientId))names.set(b.invoice.clientId,customer(b.invoice).name);
 const clientOptions=[...names].sort((a,b)=>a[1].localeCompare(b[1],'es')).map(([id,name])=>`<option value="${esc(id)}" ${id===owner?'selected':''}>${esc(name)}</option>`).join('');
 const value=selected.reduce((n,id)=>n+(open.find(b=>b.invoice.id===id)?.pendingCents||0),0);showDialog(`<h2>${pay?'Aplicar saldo disponible':'Registrar un cobro'}</h2><p>${pay?`Ingreso de ${currency(pay.amountCents)} · Disponible ${currency(available(db,pay))}`:'Registra el ingreso una sola vez y repártelo entre las facturas que paga. También puedes guardarlo como anticipo.'}</p><form id="finance-payment-form" data-payment-id="${esc(paymentId||'')}">${!pay&&selected.length===1?`<div class="payment-kind" role="group" aria-label="Tipo de cobro"><button type="button" class="btn" data-fa="payment-full" aria-pressed="true">Pago completo</button><button type="button" class="btn" data-fa="payment-partial" aria-pressed="false">Pago parcial</button><span>Indica solo el importe recibido; el resto seguirá pendiente.</span></div>`:''}<div class="payment-layout"><div><div class="fields"><div class="field"><label for="pay-amount">${pay?'Saldo disponible':'Importe recibido (€)'}</label><input id="pay-amount" name="amount" inputmode="decimal" value="${pay?(available(db,pay)/100).toFixed(2):value?(value/100).toFixed(2):''}" ${pay?'readonly':''} required></div><div class="field"><label for="pay-date">${pay?'Fecha de aplicación':'Fecha de ingreso'}</label><input id="pay-date" name="date" type="date" value="${today()}" max="${today()}" required></div><div class="field full"><label for="pay-name">Nombre del pago (opcional)</label><input id="pay-name" name="name" value="${esc(pay?.name||'')}" ${pay?'readonly':''} maxlength="200" placeholder="Ej.: Transferencia octubre · La Consulta"><small>Si lo dejas vacío, se usará la referencia o el pagador.</small></div><div class="field full"><label for="pay-client">Cliente que paga</label><select id="pay-client" name="clientId" required ${pay&&owner?'disabled':''}><option value="">Elige el cliente</option>${clientOptions}</select><small>${pay?'El saldo solo se aplica a facturas de este cliente.':'Solo aparecen sus facturas pendientes.'}</small></div><div class="field full"><label for="pay-account">Cuenta receptora</label><input id="pay-account" name="account" value="${esc(pay?.account||'Caja de Arquitectos')}" ${pay?'readonly':''} required list="account-suggestions"><datalist id="account-suggestions">${[...new Set(db.payments.map(p=>p.account))].map(a=>`<option value="${esc(a)}">`).join('')}</datalist></div><div class="field"><label for="pay-method">Método</label><select id="pay-method" name="method" ${pay?'disabled':''}>${[['transfer','Transferencia'],['confirming','Confirming'],['cash','Efectivo'],['other','Otro']].map(([v,l])=>`<option value="${v}" ${pay?.method===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="pay-ref">Referencia / concepto bancario</label><input id="pay-ref" name="reference" value="${esc(pay?.reference||'')}" ${pay?'readonly':''} maxlength="1000"></div>${!pay?`<div class="field full"><label for="pay-attachment">Justificante (opcional)</label><input id="pay-attachment" name="attachment" type="file" accept="application/pdf,image/png,image/jpeg"><small>PDF, PNG o JPG · máximo 10 MB</small></div><div class="field full"><label for="pay-notes">Observaciones</label><textarea id="pay-notes" name="notes" rows="2"></textarea></div>`:''}</div></div><div class="allocation-area"><div class="sectionhead"><h3>Repartir entre facturas</h3><button type="button" class="clear-link" data-fa="sum-selected">Usar suma seleccionada</button></div><div class="search allocation-search">${icon('search')}<input id="allocation-search" placeholder="Buscar cliente o factura…" aria-label="Buscar facturas para repartir"></div><div class="allocation-list">${allocationRows(owner,selected)}</div><div id="allocation-summary" class="allocation-summary" aria-live="polite"></div><p class="summary-note">Un cobro solo se aplica a facturas de su cliente. Las diferencias de hasta 0,02 € se registran como redondeo. Cualquier saldo mayor queda a favor del cliente.</p></div></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-fa="close">Cancelar</button><button class="btn primary" type="submit">${pay?'Aplicar saldo':'Guardar cobro'}</button></div></form>`,true);updateAllocationSummary();}
 let paymentOpen=[];
 function allocationRows(clientId,selected=[]){const list=paymentOpen.filter(b=>b.invoice.clientId===clientId);return list.length?list.map(b=>`<label class="allocation-row" data-allocation-row data-search="${esc((b.invoice.number+' '+customer(b.invoice).name).toLowerCase())}"><input type="checkbox" class="alloc-check small-check" data-invoice="${esc(b.invoice.id)}" ${selected.includes(b.invoice.id)?'checked':''}><span><strong>${esc(b.invoice.number)}</strong><small>${esc(customer(b.invoice).name)}</small><small>Pendiente ${currency(b.pendingCents)}</small></span><input class="alloc-amount" data-pending-cents="${b.pendingCents}" inputmode="decimal" aria-label="Aplicar a ${esc(b.invoice.number)}" data-invoice="${esc(b.invoice.id)}" value="${(b.pendingCents/100).toFixed(2)}"></label>`).join(''):`<p class="summary-note">${clientId?'Este cliente no tiene facturas pendientes. El ingreso quedará como anticipo.':'Elige el cliente que ha pagado para ver sus facturas pendientes.'}</p>`;}
 function receiptClient(db,p){if(p.clientId)return p.clientId;const clients=new Set(db.allocations.filter(a=>a.paymentId===p.id).map(a=>db.invoices.find(i=>i.id===a.invoiceId)?.clientId).filter(Boolean));return clients.size===1?[...clients][0]:'';}
 function syncSingleAllocation(){const checked=modal.querySelectorAll('.alloc-check:checked');if(checked.length!==1)return;const field=modal.querySelector(`.alloc-amount[data-invoice="${CSS.escape(checked[0].dataset.invoice)}"]`);if(field.dataset.manual==='true')return;const input=modal.querySelector('#pay-amount'),value=cents(input.value);field.value=input.value.trim()&&Number.isFinite(value)?(Math.max(0,Math.min(value,Number(field.dataset.pendingCents)))/100).toFixed(2):'';}
 function setPaymentMode(partial){const checked=modal.querySelectorAll('.alloc-check:checked');if(checked.length!==1)return toast('Selecciona una sola factura para utilizar esta opción.');const field=modal.querySelector(`.alloc-amount[data-invoice="${CSS.escape(checked[0].dataset.invoice)}"]`);field.dataset.manual='false';const input=modal.querySelector('#pay-amount');input.value=partial?'':(Number(field.dataset.pendingCents)/100).toFixed(2);modal.querySelector('[data-fa="payment-partial"]').setAttribute('aria-pressed',String(partial));modal.querySelector('[data-fa="payment-full"]').setAttribute('aria-pressed',String(!partial));syncSingleAllocation();updateAllocationSummary();input.focus();}
 function allocationValues(){return [...modal.querySelectorAll('.alloc-check:checked')].map(c=>({invoiceId:c.dataset.invoice,amountCents:cents(modal.querySelector(`.alloc-amount[data-invoice="${CSS.escape(c.dataset.invoice)}"]`).value)}));}
 function updateAllocationSummary(){const el=modal.querySelector('#allocation-summary');if(!el)return;const value=cents(modal.querySelector('#pay-amount').value)||0,items=allocationValues(),applied=items.reduce((n,a)=>n+(Number.isFinite(a.amountCents)?a.amountCents:0),0),diff=value-applied;const pending=items.reduce((n,a)=>{const field=modal.querySelector(`.alloc-amount[data-invoice="${CSS.escape(a.invoiceId)}"]`);return n+Math.max(0,Number(field.dataset.pendingCents)-(Number.isFinite(a.amountCents)?a.amountCents:0));},0);for(const button of modal.querySelectorAll('.payment-kind button')){button.disabled=items.length!==1;button.setAttribute('aria-pressed',String(items.length===1&&(button.dataset.fa==='payment-partial'?pending>0:pending===0)));}el.innerHTML=`<div><span>Recibido / disponible</span><strong>${currency(value)}</strong></div><div><span>Aplicado a facturas</span><strong>${currency(applied)}</strong></div><div class="${diff<-2?'negative':''}"><span>${diff<0?'Diferencia a revisar':'Queda sin aplicar'}</span><strong>${currency(Math.abs(diff))}</strong></div>${items.length?`<div class="partial-balance"><span>Quedará pendiente en las facturas</span><strong>${currency(pending)}</strong></div>`:''}${diff!==0&&Math.abs(diff)<=2?'<small>Se registrará un ajuste automático de redondeo.</small>':''}`;}

 function invoiceHistory(id){const db=getDb(),b=balances(db,today(),true,true).find(b=>b.memberIds.includes(id));if(!b)return toast('La factura no está disponible en esta fecha.');const allAlloc=db.allocations.filter(a=>b.memberIds.includes(a.invoiceId));const movements=[...allAlloc.map(a=>({...a,collection:'allocations',label:'Cobro · '+(db.payments.find(p=>p.id===a.paymentId)?.payer||''),sign:1})),...db.adjustments.filter(a=>b.memberIds.includes(a.invoiceId)).map(a=>({...a,collection:'adjustments',label:'Ajuste · '+a.reason,sign:1})),...db.refunds.filter(a=>b.memberIds.includes(a.invoiceId)).map(a=>({...a,collection:'refunds',label:'Devolución · '+a.reason,sign:-1}))].sort((a,b)=>a.date.localeCompare(b.date));showDialog(`<h2>${esc(b.invoice.number)} · Historial de cobro</h2><p>${esc(customer(b.invoice).name)}</p><div class="mini-stats"><span>Total<strong>${currency(b.totalCents)}</strong></span><span>Cobrado<strong>${currency(b.paidCents)}</strong></span><span>Ajustes<strong>${currency(b.adjustedCents)}</strong></span><span>Pendiente<strong>${currency(b.pendingCents)}</strong></span></div>${statusBadge(b)}<div class="movement-list">${movements.length?movements.map(a=>`<div class="movement ${a.voidDate?'void-movement':''}"><div><strong>${date(a.date)} · ${esc(a.label)}</strong><small>${a.voidDate?'Anulado: '+esc(a.voidReason):a.paymentId?`<button class="clear-link" data-fa-payment="${esc(a.paymentId)}">Ver transferencia</button>`:''}</small></div><strong>${a.sign<0?'−':''}${currency(a.amountCents)}</strong>${!a.voidDate&&!db.payments.find(p=>p.id===a.paymentId)?.restricted?`<button class="iconbtn" data-fa-void="${esc(a.id)}" data-collection="${a.collection}" aria-label="Anular movimiento">${icon('trash')}</button>`:''}</div>`).join(''):'<p class="summary-note">Sin cobros registrados.</p>'}</div><div class="actions">${b.pendingCents>0?`<button class="btn" data-fa-adjust="${esc(b.invoice.id)}">Registrar ajuste</button><button class="btn primary" data-fa-collect="${esc(b.invoice.id)}">Registrar cobro</button>`:''}<button class="btn" data-fa-invoice="${esc(b.invoice.id)}">Ver factura</button></div>`,true);}
 function paymentDetail(id){const db=getDb(),p=db.payments.find(p=>p.id===id);if(!p)return;const alloc=db.allocations.filter(a=>a.paymentId===id),refunds=db.refunds.filter(r=>r.paymentId===id);showDialog(`<h2>${esc(paymentName(p))}</h2><p>${esc(p.payer)} · ${date(p.date)} · ${esc(p.method==='confirming'?'Confirming':p.method==='cash'?'Efectivo':'Transferencia')} · ${esc(p.account)}</p>${p.restricted?'<div class="notice">Se muestra solo la parte aplicada a tus facturas. El administrador gestiona el ingreso completo y su justificante.</div>':''}<div class="mini-stats"><span>${p.restricted?'Aplicado a tus facturas':'Importe recibido'}<strong>${currency(paymentAmount(db,p,state.asOf))}</strong></span><span>Saldo sin aplicar<strong>${currency(available(db,p))}</strong></span></div><p class="payment-reference">${esc(p.reference||'Sin referencia bancaria')}${p.notes?'<br>'+esc(p.notes):''}</p>${p.attachmentId?`<a class="btn" href="${scopedUrl('/api/attachments/'+encodeURIComponent(p.attachmentId))}" download>Descargar justificante</a>`:''}${p.voidDate?`<div class="notice">Anulado el ${date(p.voidDate)}: ${esc(p.voidReason)}</div>`:''}<h3 style="margin-top:24px">Facturas y devoluciones asociadas</h3><div class="movement-list">${alloc.map(a=>{const i=db.invoices.find(i=>i.id===a.invoiceId);return `<div class="movement ${a.voidDate?'void-movement':''}"><div><button class="rowlink" data-fa-history="${esc(a.invoiceId)}">${esc(i?.number||'Factura')}</button><small>${esc(i?customer(i).name:'')} · ${date(a.date)} ${a.voidDate?'· Anulado':''}</small></div><strong>${currency(a.amountCents)}</strong></div>`;}).join('')}${refunds.map(r=>`<div class="movement ${r.voidDate?'void-movement':''}"><span>Devolución · ${date(r.date)}<small>${esc(r.reason)}</small></span><strong>−${currency(r.amountCents)}</strong>${!r.voidDate&&!p.restricted?`<button class="iconbtn" data-fa-void="${esc(r.id)}" data-collection="refunds" aria-label="Anular devolución">${icon('trash')}</button>`:''}</div>`).join('')}${db.paymentAdjustments.filter(a=>a.paymentId===id).map(a=>`<div class="movement"><span>Redondeo de sobrante ${a.voidDate?'(anulado)':''}</span><strong>${currency(a.amountCents)}</strong>${!a.voidDate&&!db.payments.find(p=>p.id===a.paymentId)?.restricted?`<button class="iconbtn" data-fa-void="${esc(a.id)}" data-collection="paymentAdjustments" aria-label="Anular redondeo">${icon('trash')}</button>`:''}</div>`).join('')}${!alloc.length?'<p class="summary-note">Ingreso registrado como anticipo sin facturas asignadas.</p>':''}</div><div class="actions">${!p.voidDate&&!p.restricted?`${available(db,p)>0?`<button class="btn primary" data-fa-allocate="${esc(id)}">Aplicar saldo</button>`:''}<button class="btn" data-fa-refund="${esc(id)}">Registrar devolución</button><button class="btn danger" data-fa-void="${esc(id)}" data-collection="payments">Anular cobro</button>`:''}<button class="btn" data-fa="close">Cerrar</button></div>`,true);}
 function adjustmentForm(id){const b=balances(getDb(),today(),true,true).find(b=>b.memberIds.includes(id));showDialog(`<h2>Ajustar saldo · ${esc(b.invoice.number)}</h2><p>Liquida parte de la deuda sin registrar un nuevo ingreso bancario. Pendiente: ${currency(b.pendingCents)}.</p><form id="finance-adjustment-form" data-invoice="${esc(id)}"><div class="fields"><div class="field"><label for="adj-amount">Importe del ajuste (€)</label><input id="adj-amount" name="amount" inputmode="decimal" value="${(b.pendingCents/100).toFixed(2)}" required></div><div class="field"><label for="adj-date">Fecha</label><input id="adj-date" name="date" type="date" value="${today()}" max="${today()}" required></div><div class="field full"><label for="adj-type">Clasificación</label><select id="adj-type" name="adjustmentType"><option value="confirming_fee">Gasto de confirming</option><option value="compensation">Compensación documentada</option><option value="rounding">Redondeo (hasta 0,02 €)</option><option value="other">Otro ajuste justificado</option></select></div><div class="field full"><label for="adj-reason">Motivo / referencia del documento</label><textarea id="adj-reason" name="reason" required></textarea></div></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-fa="close">Cancelar</button><button type="submit" class="btn primary">Registrar ajuste</button></div></form>`);}
 function refundForm(paymentId){const db=getDb(),p=db.payments.find(p=>p.id===paymentId);const ids=[...new Set(db.allocations.filter(a=>a.paymentId===paymentId&&!a.voidDate).map(a=>a.invoiceId))];showDialog(`<h2>Registrar devolución</h2><p>El movimiento resta dinero recibido y, si corresponde a una factura, reabre su saldo pendiente.</p><form id="finance-refund-form" data-payment="${esc(paymentId)}"><div class="fields"><div class="field full"><label for="ref-invoice">Qué se devuelve</label><select id="ref-invoice" name="invoiceId">${available(db,p)>0?`<option value="">Anticipo sin aplicar · ${currency(available(db,p))}</option>`:''}${ids.map(id=>`<option value="${esc(id)}">Cobro de ${esc(db.invoices.find(i=>i.id===id)?.number)}</option>`).join('')}</select></div><div class="field"><label for="ref-amount">Importe devuelto (€)</label><input id="ref-amount" name="amount" inputmode="decimal" required></div><div class="field"><label for="ref-date">Fecha</label><input id="ref-date" name="date" type="date" value="${today()}" max="${today()}" required></div><div class="field full"><label for="ref-reason">Motivo</label><textarea id="ref-reason" name="reason" required></textarea></div></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-fa="close">Cancelar</button><button type="submit" class="btn primary">Registrar devolución</button></div></form>`);}
 function voidForm(collection,id){showDialog(`<h2>Anular movimiento</h2><p>Se conservará el original en el historial. Los saldos se recalcularán a partir de hoy.</p><form id="finance-void-form" data-collection="${collection}" data-id="${esc(id)}"><div class="field"><label for="void-reason">Motivo de la anulación</label><textarea id="void-reason" name="reason" required></textarea></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-fa="close">Cancelar</button><button type="submit" class="btn danger">Confirmar anulación</button></div></form>`);}
 function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 function csvDownload(rows,name){const q=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"';download(new Blob(['\ufeff'+rows.map(r=>r.map(q).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),name);}
 // E-mails and VERI*FACTU records live on the server; without them those two columns stay generic instead of failing.
 async function excel(){const r=range();if(!r.start||!r.end||r.start>r.end||!state.asOf||state.asOf>today())return toast('Revisa el intervalo y la fecha de consulta.');const json=path=>fetch(path).then(res=>res.ok?res.json():{}).catch(()=>({}));const [mail,vf]=await Promise.all([json('/api/mail/sent'),json('/api/verifactu/records')]);const file=incomeWorkbook({db:getDb(),period:{mode:state.mode,year:state.year,quarter:state.quarter,month:state.month,start:state.start,end:state.end},asOf:state.asOf,clientId:state.client,ownerLabel,mail:mail.sent||{},records:vf.records||[],restricted:!isAdmin()});download(new Blob([file.bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),file.name);}
 function report(payments=false){const db=getDb(),r=range();if(payments){csvDownload([['Emisor','NIF emisor'],[db.company.name,db.company.nif],['Fecha','Pagador','Cuenta','Referencia','Recibido EUR','Sin aplicar EUR','Anulado'],...db.payments.filter(p=>!p.vfTest&&p.date>=r.start&&p.date<=r.end&&p.date<=state.asOf).map(p=>[p.date,p.payer,p.account,p.reference,paymentAmount(db,p,state.asOf)/100,available(db,p,state.asOf)/100,p.voidDate||''])],(db.company.name||'Emisor')+'-cobros.csv');return;}const s=summary(db,r,state.asOf,state.client);csvDownload([['Emisor','NIF emisor'],[db.company.name,db.company.nif],['Factura','Cliente','Fecha emisión','Total EUR','Cobrado EUR','Ajustes EUR','Pendiente EUR','Estado','Fecha de consulta'],...s.cohort.map(b=>[b.invoice.number,customer(b.invoice).name,b.original.date,b.totalCents/100,b.paidCents/100,b.adjustedCents/100,b.pendingCents/100,statusName[b.status],state.asOf])],(db.company.name||'Emisor')+'-analisis.csv');}
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.faTab){state.tab=b.dataset.faTab;state.search='';state.selected.clear();if(state.tab==='allInvoices')state.status='all';if(state.tab==='pending')state.status='pending';render();}else if(b.dataset.faInvoice){modal.close();openInvoice(b.dataset.faInvoice);}else if(b.dataset.faHistory){invoiceHistory(b.dataset.faHistory);}else if(b.dataset.faPayment){paymentDetail(b.dataset.faPayment);}else if(b.dataset.faCollect){paymentForm([b.dataset.faCollect]);}else if(b.dataset.faAdjust){adjustmentForm(b.dataset.faAdjust);}else if(b.dataset.faAllocate){paymentForm([],b.dataset.faAllocate);}else if(b.dataset.faRefund){refundForm(b.dataset.faRefund);}else if(b.dataset.faVoid){voidForm(b.dataset.collection,b.dataset.faVoid);}else if(b.dataset.faMonth){state.mode='month';state.year=b.dataset.faMonth.slice(0,4);state.month=b.dataset.faMonth.slice(5);state.tab='pending';render();}else switch(b.dataset.fa){case'close':modal.close();modal.className='';break;case'import':if(!isAdmin())return toast('La importación la gestiona un administrador.');await beforeAction();state.tab='import';importer.render();break;case'new-payment':await beforeAction();paymentForm();break;case'all-outstanding':state.mode='custom';state.start=getDb().invoices.filter(i=>i.status==='issued'&&!i.isExample&&!i.isDemo&&!i.vfTest).map(i=>i.date).sort()[0]||today();state.end=today();state.status='pending';state.tab='pending';render();break;case'collect-selected':{const db=getDb(),clients=new Set([...state.selected].map(id=>db.invoices.find(i=>i.id===id)?.clientId));if(clients.size>1){toast('Un cobro solo puede pagar facturas de un mismo cliente. Selecciona facturas de un solo cliente.');break;}paymentForm([...state.selected]);break;}case'payment-partial':setPaymentMode(true);break;case'payment-full':setPaymentMode(false);break;case'sum-selected':modal.querySelector('#pay-amount').value=(allocationValues().reduce((n,a)=>n+a.amountCents,0)/100).toFixed(2);updateAllocationSummary();break;case'report':report();break;case'excel':await excel();break;case'report-payments':report(true);break;}}catch(e){toast(e.message);}});
 document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){state[el.dataset.filter]=el.value;state.selected.clear();render();}if(el.dataset.pick){if(el.checked)state.selected.add(el.dataset.pick);else state.selected.delete(el.dataset.pick);const button=document.querySelector('[data-fa="collect-selected"]');if(button){button.disabled=!state.selected.size;button.innerHTML='Registrar cobro de la selección ('+state.selected.size+')';}}if(el.id==='fa-status'){state.status=el.value;state.selected.clear();render();}if(el.id==='fa-sort'){state.sort=el.value;render();}if(el.id==='fa-group'){state.group=el.checked;render();}if(el.classList.contains('alloc-check')){syncSingleAllocation();updateAllocationSummary();}if(el.id==='pay-client'){modal.querySelector('.allocation-list').innerHTML=allocationRows(el.value);const search=modal.querySelector('#allocation-search');if(search)search.value='';updateAllocationSummary();}});
 document.addEventListener('input',e=>{const el=e.target;if(el.id==='fa-search'){const start=el.selectionStart;state.search=el.value;if(['pending','allInvoices'].includes(state.tab)){const rows=document.querySelector('#finance-invoice-rows');const list=filteredBalances();rows.innerHTML=rowsTable(list,true);document.querySelector('#finance-result-label').textContent=`${list.length} facturas · ${currency(list.reduce((n,b)=>n+b.pendingCents,0))} pendiente`;}else{render();const input=document.querySelector('#fa-search');input.focus();input.setSelectionRange(start,start);}}if(el.id==='allocation-search'){const q=el.value.toLowerCase();modal.querySelectorAll('[data-allocation-row]').forEach(row=>row.hidden=!row.dataset.search.includes(q));}if(el.classList.contains('alloc-amount'))el.dataset.manual='true';if(el.id==='pay-amount')syncSingleAllocation();if(el.id==='pay-amount'||el.classList.contains('alloc-amount'))updateAllocationSummary();});
 document.addEventListener('submit',async e=>{const form=e.target;if(!form.id.startsWith('finance-'))return;e.preventDefault();const btn=form.querySelector('button[type="submit"]');btn.disabled=true;form.querySelector('.form-error').textContent='';try{const data=Object.fromEntries(new FormData(form));let cmd;
 if(form.id==='finance-payment-form'){const allocations=allocationValues();cmd=form.dataset.paymentId?{type:'allocate',paymentId:form.dataset.paymentId,date:data.date,allocations,rounding:true}:{type:'payment',amountCents:cents(data.amount),date:data.date,name:data.name,clientId:data.clientId,account:data.account,reference:data.reference,method:data.method,notes:data.notes,allocations,rounding:true};const file=form.querySelector('#pay-attachment')?.files[0];if(file&&!form.dataset.attachmentId){const r=await fetch('/api/attachments',{method:'POST',headers:{'Content-Type':file.type,'X-Filename':encodeURIComponent(file.name)},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);form.dataset.attachmentId=d.id;}if(form.dataset.attachmentId)cmd.attachmentId=form.dataset.attachmentId;}
 else if(form.id==='finance-adjustment-form')cmd={type:'adjustment',invoiceId:form.dataset.invoice,amountCents:cents(data.amount),date:data.date,adjustmentType:data.adjustmentType,reason:data.reason};
 else if(form.id==='finance-refund-form')cmd={type:'refund',paymentId:form.dataset.payment,invoiceId:data.invoiceId||null,amountCents:cents(data.amount),date:data.date,reason:data.reason};
 else if(form.id==='finance-void-form')cmd={type:'void',collection:form.dataset.collection,id:form.dataset.id,reason:data.reason};
 cmd.operationId=form.dataset.operationId||=crypto.randomUUID();await apiCommand(cmd);modal.close();modal.className='';state.selected.clear();ctx.renderApp();toast('Movimiento guardado en este equipo');
 }catch(err){form.querySelector('.form-error').textContent=err.message;btn.disabled=false;}});
 function invoicePanel(invoice){if(invoice.isExample)return '';const b=balances(getDb(),today(),true,true).find(b=>b.memberIds.includes(invoice.id));if(!b)return '';return `<div class="invoice-payment-panel">${statusBadge(b)}<div class="sumrow"><span>Cobrado</span><strong>${currency(b.paidCents)}</strong></div>${b.adjustedCents?`<div class="sumrow"><span>Ajustes</span><strong>${currency(b.adjustedCents)}</strong></div>`:''}<div class="sumrow"><span>Pendiente</span><strong>${currency(b.pendingCents)}</strong></div>${b.pendingCents>0?`<button class="btn primary" data-fa-collect="${esc(b.invoice.id)}">Registrar cobro</button>`:''}<button class="btn ghost" data-fa-history="${esc(invoice.id)}">Historial de cobros</button></div>`;}
 return {render,invoicePanel};
}
